import org.apache.commons.beanutils.BeanUtilsBean;
import org.apache.commons.beanutils.PropertyUtilsBean;
import org.apache.commons.beanutils.ConvertUtilsBean;

public void setProperty(Object bean, String name, Object value)
        throws IllegalAccessException, InvocationTargetException {

    // Trace logging (if enabled)
    if (log.isTraceEnabled()) {
        log.trace("setProperty(" + bean + ", " + name + ", " + value + ")");
    }

    // Resolve any nested expression to get the actual target bean
    PropertyUtilsBean propertyUtils = new PropertyUtilsBean();
    Resolver resolver = propertyUtils.getResolver();
    Object target = bean;
    while (resolver.hasNested(name)) {
        try {
            target = propertyUtils.getProperty(target, resolver.next(name));
            if (target == null) {
                return;
            }
            name = resolver.remove(name);
        } catch (NoSuchMethodException e) {
            return; // Skip this property setter
        }
    }

    // Convert the specified value to the required type
    ConvertUtilsBean convertUtils = new ConvertUtilsBean();
    Object newValue = convertUtils.convert(value, propertyUtils.getPropertyType(target, name));

    // Invoke the setter method
    try {
        propertyUtils.setProperty(target, name, newValue);
    } catch (NoSuchMethodException e) {
        throw new InvocationTargetException(e, "Cannot set " + name);
    }
}

